  from jsonb_to_recordset($seed$[{"track_code":"foundation_v1","day":1,"card_en":{"today":[{"label":"What it is","text":"Your Foundation Track: 14 days, one card a day. Week 1 helps us understand you, one pillar a day. Week 2 is about action."},{"label":"Why it matters","text":"Lasting change starts from where you really are, not from a perfect plan. Knowing your starting point and where you want to go lets everything after fit you."},{"label":"How we use it","text":"Your answers and check-ins shape your week-2 actions, your first-week summary on day 7 and your review call with Thomas on day 14."}],"try_label":"First thing to try · a mini morning routine","tip":"Put a glass of water by your bed tonight, so tomorrow's first step is already waiting.","evolve":[{"when":"Tomorrow","text":"Photograph what you eat. That habit runs all 14 days."},{"when":"Day 3","text":"1 minute of movement joins your morning, and your evening routine begins."},{"when":"Day 7","text":"Your full day: a 5-minute morning flow and a daily exercise snack."}],"library":[],"pillar":"Where you are, where you're going"}},{"track_code":"foundation_v1","day":2,"card_en":{"today":[{"label":"What it is","text":"What you eat, when, and how much: the material your body builds and repairs with, and the fuel for your energy."},{"label":"Why it matters","text":"Food shapes your energy, hunger, mood, sleep and recovery. Small changes in what and when you eat often make a big difference."},{"label":"How we use it","text":"Your answers and your meal photos show your real pattern. From them we choose the changes that will help you most, with ideas from foods you already eat."}],"try_label":"First thing to try · one habit for all 14 days","tip":"Photograph before the first bite, drinks and snacks included. A quick photo beats a perfect one.","evolve":[{"when":"Tomorrow","text":"Your morning grows with 1 minute of movement, and your evening routine begins."},{"when":"Day 4","text":"Daylight in the morning, your phone out of the bedroom."},{"when":"Days 8–9","text":"Breakfast and lunch become the focus, built from your photos."}],"library":[],"pillar":"Pillar 1 · Nutrition"}},{"track_code":"foundation_v1","day":3,"card_en":{"today":[{"label":"What it is","text":"Not sport: your functional capacity. How easily your body does what your life asks of it: getting up, carrying, climbing stairs, hiking."},{"label":"Why it matters","text":"Capacity is built or lost by what you do every day. Long hours of sitting slowly take it away; small, regular movement keeps it and builds it."},{"label":"How we use it","text":"Your answers set the right starting level for you and keep every movement we suggest safe. We start with little and often."}],"try_label":"First thing to try · your morning grows, your evening begins","tip":"No time for an exercise snack? Take the stairs once. That counts.","evolve":[{"when":"Tomorrow","text":"5 minutes of daylight; your phone sleeps outside the bedroom."},{"when":"Day 7","text":"Your minute of movement becomes a 5-minute flow, and the exercise snack becomes daily."},{"when":"Days 10–12","text":"Easy strength, then a 10-minute morning flow."}],"library":[{"kind":"Lesson","title":"Exercise snacks: small signals that add up"}],"pillar":"Pillar 2 · Movement"}},{"track_code":"foundation_v1","day":4,"card_en":{"today":[{"label":"What it is","text":"The time your body repairs, your brain sorts the day and your rhythm resets."},{"label":"Why it matters","text":"After a poor night, hunger is louder, cravings stronger, mood shorter and effort harder. Regular times and light set your body clock."},{"label":"How we use it","text":"Your usual pattern tells us where to start, and your times decide when your reminders arrive. Your morning check-in records each night."}],"try_label":"First thing to try · one for the morning, one for the night","tip":"No time to go outside? Have your coffee at the brightest window.","evolve":[{"when":"Tomorrow","text":"Box breathing and one good thing join your evening."},{"when":"Day 11","text":"Your full evening routine: last meal earlier, screens off, a book, 10 minutes to wind down."}],"library":[],"pillar":"Pillar 3 · Sleep"}},{"track_code":"foundation_v1","day":5,"card_en":{"today":[{"label":"What it is","text":"The load you carry, from work, family, health or big changes, and how well you recover from it."},{"label":"Why it matters","text":"When the load stays high, it shows up in your sleep, appetite, energy, digestion and mood. Recovery is what brings your body back to calm."},{"label":"How we use it","text":"Knowing where your load comes from and what already helps you lets us suggest tools that fit your life, instead of adding pressure."}],"try_label":"First thing to try · your evening grows","tip":"If four counts feel long, breathe in threes. The rhythm matters more than the number.","evolve":[{"when":"Tomorrow","text":"A short walk after lunch: your routine now covers the whole day."},{"when":"Day 11","text":"Your 2 minutes of breathing grow into 10 minutes: breathing, NSDR or gentle yoga."}],"library":[],"pillar":"Pillar 4 · Mental and emotional health"}},{"track_code":"foundation_v1","day":6,"card_en":{"today":"Six days, four pillars: nutrition, movement, sleep, and your mental and emotional health. You've told us where you are and where you want to go, and you've built a small routine without really noticing. Here it is, in the four moments of your day. One new moment today: after lunch.","try_label":"New today · after lunch","tip":"Put your walking shoes by the door before lunch.","evolve":[{"when":"Tomorrow","text":"A 5-minute morning flow and one exercise snack a day."},{"when":"Week 2","text":"One focus a day: breakfast, lunch, strength, evening, morning."},{"when":"Day 13","text":"You choose what you keep."}],"library":[],"pillar":"Recap"}},{"track_code":"foundation_v1","day":7,"card_en":{"today":"One week. Today everything comes together in one full day, with a little more movement: your minute in the morning becomes a 5-minute flow inspired by qi gong, and the exercise snack becomes daily. Thomas is reviewing your first week; your summary appears here once he has read it.","try_label":"New today · a little more movement","tip":"Link the new to the old: your flow right after your glass of water.","evolve":[{"when":"Day 8","text":"Breakfast: protein first."},{"when":"Day 9","text":"Lunch, and a 10-minute walk after it."},{"when":"Day 10","text":"Your exercise snack becomes a strength routine."},{"when":"Days 11–12","text":"Your full evening, then a longer morning flow."}],"library":[],"pillar":"Everything together"}},{"track_code":"foundation_v1","day":8,"card_en":{"today":"Protein is your body's building material: muscle, bones, skin, your immune system. Your body can't store it the way it stores fat or sugar, so it needs some regularly across the day, and more as we age to keep our muscle. Many people eat little in the morning and most at night. Today, protein moves to breakfast.","try_label":"New today","tip":"Boil a few eggs for the week, or keep Greek yogurt in the fridge: breakfast protein in one minute.","evolve":[{"when":"Tomorrow","text":"Lunch: protein, vegetables, complex carbs, and your after-lunch walk doubles to 10 minutes."},{"when":"Day 10","text":"Easy strength."}],"library":[{"kind":"Infographic","title":"Protein through the day"}]}},{"track_code":"foundation_v1","day":9,"card_en":{"today":"Lunch decides your afternoon. Fast carbs (white bread, white pasta, sweet drinks) often mean a quick rise and a dip around three. Build your plate in three parts: half vegetables, a palm of protein, a quarter complex carbs. Complex carbs come with fibre, so they give steadier energy. Then the most important part: a 10-minute walk.","try_label":"New today","tip":"Lunch out? Ask for extra vegetables and choose the whole-grain side.","evolve":[{"when":"Tomorrow","text":"Your exercise snack becomes a 5-minute strength routine."},{"when":"Day 11","text":"Your full evening routine."}],"library":[{"kind":"Infographic","title":"The plate that holds you"}]}},{"track_code":"foundation_v1","day":10,"card_en":{"today":"Muscle is one of the best long-term investments you can make: it holds you up, protects your joints, helps your body handle sugar and keeps you independent as you age. Your exercise snack becomes a 5-minute routine, at home, no equipment. Go slowly and stop if anything hurts: easier is always fine.","try_label":"New today","tip":"Do your routine while the kettle boils or the coffee runs.","evolve":[{"when":"Tomorrow","text":"Your full evening routine."},{"when":"Day 12","text":"Your morning flow grows to 10 minutes."}],"library":[]}},{"track_code":"foundation_v1","day":11,"card_en":{"today":"Tonight your evening routine is complete. Last meal 2–3 hours before bed, so your body can rest rather than digest. An hour before bed: screens off, lights low, a book instead of the phone. Then 10 minutes to wind down: slow breathing, NSDR or gentle yoga. Your stretch and box breathing grow into this.","try_label":"New today · the full routine","tip":"Set an alarm for 'screens off', and choose tonight's book now.","evolve":[{"when":"Tomorrow","text":"Your morning flow grows to 10 minutes, with short movement breaks."},{"when":"Day 13","text":"You choose what you keep."}],"library":[{"kind":"Audio","title":"10-minute NSDR"}]}},{"track_code":"foundation_v1","day":12,"card_en":{"today":"Moving early wakes your body, gets your circulation going and, outside, gives you daylight for your body clock. And what's done first thing gets done. Your flow grows from five to ten minutes. During the day, if you sit for long, stand up every hour or two and move for two minutes.","try_label":"New today","tip":"Stand up whenever you take a call.","evolve":[{"when":"Tomorrow","text":"Nothing new: you choose what you keep."},{"when":"Day 14","text":"Your two weeks, and your 20-minute review call."}],"library":[]}},{"track_code":"foundation_v1","day":13,"card_en":{"today":"Look at what you've built in twelve days. There's nothing new today: choose the actions you want to keep after these two weeks. They stay in your app. A few habits you keep are worth more than ten you try once.","try_label":"New today","tip":"Keep the ones you'd miss, not the ones you think you should.","evolve":[{"when":"Tomorrow","text":"Your two weeks: before and after, and your review call."},{"when":"After day 14","text":"The actions you keep stay in your app."}],"library":[]}},{"track_code":"foundation_v1","day":14,"card_en":{"today":"Two weeks ago you started. Today you see your check-ins from your first days next to your last days, tell us how it was, and book your 20-minute review call with Thomas once it's open to you.","try_label":"New today","tip":"Write down one question for Thomas before your call.","evolve":[{"when":"Next","text":"Keep going with the app, or go deeper with a personal programme. You decide together on your call."}],"library":[]}}]$seed$::jsonb) as x(track_code text, day int, card_en jsonb)
